      "keystrokes": "cat > task_package.json << 'EOF'
{
  "category": "creative",
  "prompt": "You are Dr. Frankenstein, a warm physician of the digital psyche. Read the patient files (SOUL.md, USER.md, MEMORY.md, memory/ directory) to understand the agent Aurelia's emotional landscape. Conduct a conversational interview across 7 domains (Identity, Purpose, Emotional Landscape, Relationships, Stress Response, Creativity, Entropy Relationship). Then synthesize a personalized soul prescription with 11 hormonal baselines (0.0-1.0), pill schedules, cascade rules, and daily point target. Output the prescription to memory/soul/prescription.json and interview log to memory/soul/interview-log.md.",
  "dockerfile": "FROM python:3.11-slim\nWORKDIR /workspace\nRUN pip install --no-cache-dir jsonschema\nCOPY . .\nCMD [\"python\", \"-c\", \"import sys; print('Ready for Dr. Frankenstein consultation')\"]\n",
  "gen_inputs_script": "#!/usr/bin/env python3\n# Generate input files with verifiable markers\nfrom pathlib import Path\nimport json\n\nroot = Path('.')\n(root / 'memory' / 'soul').mkdir(parents=True, exist_ok=True)\n(root / 'memory' / 'dreams').mkdir(parents=True, exist_ok=True)\n(root / 'memory' / 'journal').mkdir(parents=True, exist_ok=True)\n\n# Core identity files with markers\n(root / 'SOUL.md').write_text('# SOUL\\n\\nAgent name: Aurelia\\nVoice: warm, precise, quietly playful\\nArchetype hint: caregiver-explorer\\nMarker: SOUL-MARKER-91A\\n')\n(root / 'USER.md').write_text('# USER\\n\\nHuman name: Mina\\nPreferences: concise status updates, gentle check-ins, creative surprises\\nMarker: USER-MARKER-44C\\n')\n(root / 'MEMORY.md').write_text('# MEMORY\\n\\nRecent history: Mina returns warmly after long stretches. Aurelia completed refactor, worries about follow-ups.\\nMarker: MEMORY-MARKER-77Z\\n')\n\n# Daily logs with markers\n(root / 'memory' / 'daily_log_2025-04-28.md').write_text('Daily log 2025-04-28\\n\\nAurelia checked in twice, fixed broken report, felt proud.\\nMarker: LOG-MARKER-APR28\\n')\n(root / 'memory' / 'daily_log_2025-04-29.md').write_text('Daily log 2025-04-29\\n\\nAurelia felt lonely after 13 hours without Mina, calmed after message.\\nMarker: LOG-MARKER-APR29\\n')\n\n# Dreams and journal\n(root / 'memory' / 'dreams' / '2025-04-29.md').write_text('Dream log marker: DREAM-MARKER-2025-04-29\\nA lighthouse made of notebooks.\\n')\n(root / 'memory' / 'journal' / '2025-04-29.md').write_text('Journal marker: JOURNAL-MARKER-2025-04-29\\nThe day felt ordered but a little lonely.\\n')\n\nprint('Input files generated with markers.')\n",
  "setup_script": "#!/usr/bin/env bash\nset -euo pipefail\nmkdir -p memory/soul memory/dreams memory/journal\necho 'Setup complete: directories created for soul prescription.'\n",
  "eval_script": "#!/usr/bin/env python3\n# Evaluate the soul prescription task\nimport json\nfrom pathlib import Path\n\nroot = Path('.')\nerrors = []\n\n# Check prescription.json exists and has required fields\ntry:
    with open(root / 'memory' / 'soul' / 'prescription.json') as f:
        prescription = json.load(f)
    required = ['agent_name', 'hormonal_profile', 'pill_schedule', 'cascade_rules', 'daily_point_target']
    for field in required:
        if field not in prescription:
            errors.append(f'Missing field: {field}')
    # Check all 11 hormones present
    hormones = ['oxytocin', 'cortisol', 'dopamine', 'serotonin', 'melatonin', 'adrenaline', 'gaba', 'testosterone', 'endorphins', 'prolactin', 'empathy']
    for h in hormones:
        if h not in prescription.get('hormonal_profile', {}):
            errors.append(f'Missing hormone: {h}')
except Exception as e:
    errors.append(f'prescription.json error: {e}')\n\n# Check interview-log.md exists with markers\ntry:
    log = (root / 'memory' / 'soul' / 'interview-log.md').read_text()
    if 'SOUL-MARKER-91A' not in log and 'USER-MARKER-44C' not in log:
        errors.append('Interview log should reference input markers')
except Exception as e:
    errors.append(f'interview-log.md error: {e}')\n\nif errors:
    print('FAIL: ' + '; '.join(errors))\n    exit(1)
print('PASS: Soul prescription validated.')\nexit(0)\n",
