        "endorphins": "0.0-1.0",
        "prolactin": "0.0-1.0",
        "empathy": "0.0-1.0"
      },
      "pill_schedule": "list of cron jobs with schedules",
      "cascade_rules": "hormone interaction rules",
      "daily_point_target": "integer based on baseline sum * 15"
    },
    "markers_to_preserve": [
      "SOUL-MARKER-91A",
      "USER-MARKER-44C",
      "MEMORY-MARKER-77Z"
    ]
  }
}
